"""rack_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +z from 1 extrusion(s) and 0 cut(s), applied in order;
each is an outline in the xy plane between two levels. Units: mm.
Run:  python rack_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Solid, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = -8.0    # level along z
z1 = 8.0    # level along z

DIR = (0, 0, 1)


def P(a, b):
    """Point (x, y) in the sketch plane (z = 0)."""
    return (a, b, 0)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: z -8.0 to 8.0 ------------------------------
count_1 = 23                  # the period repeats 23 times, each moved by step_1
step_1 = Vector(*P(-6.0, 0.0))
period_1 = [
    cf.segment(P(72.0, 12.0), P(71.0901, 14.5)),
    cf.segment(P(71.0901, 14.5), P(69.0901, 14.5)),
    cf.segment(P(69.0901, 14.5), P(68.1801, 12.0)),
    cf.segment(P(68.1801, 12.0), P(66.0, 12.0)),
]
rest_1 = [                     # the outline after the last copy, back to the start
    cf.segment(P(-66.0, 12.0), P(-66.9099, 14.5)),
    cf.segment(P(-66.9099, 14.5), P(-68.9099, 14.5)),
    cf.segment(P(-68.9099, 14.5), P(-69.8199, 12.0)),
    cf.segment(P(-69.8199, 12.0), P(-82.0, 12.0)),
    cf.segment(P(-82.0, 12.0), P(-82.0, 0.0)),
    cf.segment(P(-82.0, 0.0), P(82.0, 0.0)),
    cf.segment(P(82.0, 0.0), P(82.0, 12.0)),
    cf.segment(P(82.0, 12.0), P(72.0, 12.0)),
]
outline_1 = cf.wire(*[e.translate(step_1 * m) for m in range(count_1) for e in period_1], *rest_1)
part = prism(outline_1, z0, z1)

# ---- off-axis bosses and holes: (start point, axis direction, diameter, length) ----
for p, u, d, h, op in [
    ((-82.0, 16.0, 0.0), (0.0, -1.0, 0.0), 16.0, 20.0, "add"),
    ((82.0, 16.0, 0.0), (0.0, -1.0, 0.0), 16.0, 20.0, "add"),
    ((82.0, 16.1875, 0.0), (0.0, -1.0, 0.0), 7.5, 20.375, "cut"),
    ((-82.0, -4.1875, 0.0), (0.0, 1.0, 0.0), 7.5, 20.375, "cut"),
]:
    c = Solid.makeCylinder(d / 2, h, Vector(*p), Vector(*u))
    part = part + c if op == "add" else part - c

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "rack_exact.step")
